"""Self-contained ConnectX agent: PUCT-MCTS + small policy/value network (NumPy inference only).
Generated by submission/build_submission.py. Defines agent(observation, configuration)."""
from __future__ import annotations
import numpy as np

# ============================== game.py ==============================
"""Bitboard ConnectX engine (any rows/columns/inarow) plus a slow reference implementation.

Bit layout: column c, row r (r=0 is the BOTTOM row) is bit  c*(rows+1) + r.  The extra top bit of each
column is a sentinel that is never set, which stops runs wrapping between columns.

State fields: `cur` = checkers of the player TO MOVE, `mask` = all checkers, `moves` = plies played,
`won` = True iff the player who just moved has completed `inarow` (so the player to move has lost).

Network encoding (`to_planes`), always from the perspective of the player to move, row 0 = TOP row
(same orientation as the Kaggle `board`):
    plane 0: own checkers (player to move)      plane 1: opponent checkers
    plane 2 (only when n_planes=3): constant 1.0 if the player to move is player 1 (moved first), else 0.0
"""

import numpy as np


class Geometry:
    _cache: dict = {}

    def __init__(self, rows: int, cols: int, inarow: int):
        self.rows, self.cols, self.inarow = rows, cols, inarow
        H = rows + 1
        self.H = H
        self.bottom = [1 << (c * H) for c in range(cols)]
        self.colmask = [((1 << rows) - 1) << (c * H) for c in range(cols)]
        self.top = [1 << (c * H + rows - 1) for c in range(cols)]
        self.full_mask = sum(self.colmask)
        self.shifts = (1, H, H + 1, H - 1)
        # bit shift per (top-first row, col) cell for plane extraction
        self.cell_shift = np.array([[c * H + (rows - 1 - r) for c in range(cols)] for r in range(rows)], dtype=np.int64)
        self.center_order = sorted(range(cols), key=lambda c: (abs(c - (cols - 1) / 2), c))
        self.size = rows * cols
        self.windows = self._windows()

    def _windows(self):
        R, C, K, H = self.rows, self.cols, self.inarow, self.H
        wins = []
        for c in range(C):
            for r in range(R):
                for dc, dr in ((1, 0), (0, 1), (1, 1), (1, -1)):
                    ec, er = c + dc * (K - 1), r + dr * (K - 1)
                    if 0 <= ec < C and 0 <= er < R:
                        m = 0
                        for i in range(K):
                            m |= 1 << ((c + dc * i) * H + r + dr * i)
                        wins.append(m)
        return wins

    @classmethod
    def get(cls, rows, cols, inarow):
        k = (rows, cols, inarow)
        g = cls._cache.get(k)
        if g is None:
            g = cls._cache[k] = Geometry(rows, cols, inarow)
        return g


def has_four(b: int, g: Geometry) -> bool:
    """True if bitboard b contains `inarow` consecutive bits in any direction."""
    k = g.inarow
    for d in g.shifts:
        if k == 4:
            m = b & (b >> d)
            if m & (m >> (2 * d)):
                return True
        else:
            t = b
            for i in range(1, k):
                t &= b >> (i * d)
            if t:
                return True
    return False


class State:
    __slots__ = ("g", "cur", "mask", "moves", "won")

    def __init__(self, rows: int = 6, cols: int = 7, inarow: int = 4):
        self.g = Geometry.get(rows, cols, inarow)
        self.cur = 0
        self.mask = 0
        self.moves = 0
        self.won = False

    # ---- basic properties
    @property
    def rows(self): return self.g.rows

    @property
    def cols(self): return self.g.cols

    @property
    def inarow(self): return self.g.inarow

    @property
    def current_player(self) -> int:
        return 1 if self.moves % 2 == 0 else 2

    def copy(self) -> "State":
        s = State.__new__(State)
        s.g, s.cur, s.mask, s.moves, s.won = self.g, self.cur, self.mask, self.moves, self.won
        return s

    def legal_moves(self) -> list:
        if self.won:
            return []
        m, top = self.mask, self.g.top
        return [c for c in range(self.g.cols) if not (m & top[c])]

    def is_legal(self, col: int) -> bool:
        return 0 <= col < self.g.cols and not self.won and not (self.mask & self.g.top[col])

    def play(self, col: int) -> "State":
        """Mutating move for the player to move. Raises ValueError on an illegal column."""
        if not self.is_legal(col):
            raise ValueError(f"illegal move {col}")
        g = self.g
        new_bit = (self.mask + g.bottom[col]) & g.colmask[col]
        self.cur ^= self.mask                 # swap sides: cur becomes the next player to move
        self.mask |= new_bit
        self.won = has_four(self.cur ^ self.mask, g)   # (cur^mask) = checkers of the mover
        self.moves += 1
        return self

    def child(self, col: int) -> "State":
        return self.copy().play(col)

    def is_win(self) -> bool:
        """True iff the player who just moved has won."""
        return self.won

    def is_draw(self) -> bool:
        return (not self.won) and self.moves == self.g.size

    def is_terminal(self) -> bool:
        return self.won or self.moves == self.g.size

    def wins_with(self, col: int) -> bool:
        """Would the player to move win by playing col? (col must be legal)"""
        g = self.g
        nb = (self.mask + g.bottom[col]) & g.colmask[col]
        return has_four(self.cur | nb, g)

    def opp_wins_with(self, col: int) -> bool:
        g = self.g
        nb = (self.mask + g.bottom[col]) & g.colmask[col]
        return has_four((self.cur ^ self.mask) | nb, g)

    # ---- keys / symmetry
    def to_key(self) -> int:
        return (self.mask << (self.g.cols * self.g.H + 1)) | self.cur

    def mirror(self) -> "State":
        g = self.g
        H, C = g.H, g.cols
        blk = (1 << H) - 1
        cur = mask = 0
        for c in range(C):
            nc = C - 1 - c
            cur |= ((self.cur >> (c * H)) & blk) << (nc * H)
            mask |= ((self.mask >> (c * H)) & blk) << (nc * H)
        s = self.copy()
        s.cur, s.mask = cur, mask
        return s

    # ---- encodings
    def to_planes(self, n_planes: int = 2, out: np.ndarray | None = None) -> np.ndarray:
        g = self.g
        if out is None:
            out = np.zeros((n_planes, g.rows, g.cols), dtype=np.float32)
        sh = g.cell_shift
        out[0] = (self.cur >> sh) & 1
        out[1] = ((self.cur ^ self.mask) >> sh) & 1
        if n_planes >= 3:
            out[2] = 1.0 if self.current_player == 1 else 0.0
        return out

    def to_board(self) -> list:
        """Kaggle-style flat board (top row first, 0/1/2)."""
        g = self.g
        me, other = self.current_player, 3 - self.current_player
        mine, theirs = self.cur, self.cur ^ self.mask
        out = []
        for r in range(g.rows):
            for c in range(g.cols):
                b = 1 << (c * g.H + (g.rows - 1 - r))
                out.append(me if mine & b else (other if theirs & b else 0))
        return out

    @classmethod
    def from_board(cls, board, mark: int, rows: int = 6, cols: int = 7, inarow: int = 4) -> "State":
        board = [int(x) for x in board]
        if len(board) != rows * cols:
            raise ValueError(f"board has {len(board)} cells, expected {rows}x{cols}={rows*cols}")
        s = cls(rows, cols, inarow)
        g = s.g
        p1 = p2 = 0
        for r in range(rows):
            for c in range(cols):
                v = board[r * cols + c]
                if v:
                    b = 1 << (c * g.H + (rows - 1 - r))
                    if v == 1:
                        p1 |= b
                    elif v == 2:
                        p2 |= b
                    else:
                        raise ValueError(f"bad cell value {v}")
        s.mask = p1 | p2
        s.moves = (p1.bit_count() + p2.bit_count())
        # gravity check: every column must be a contiguous stack from the bottom
        for c in range(cols):
            col = (s.mask >> (c * g.H)) & ((1 << rows) - 1)
            if col & (col + 1):
                raise ValueError(f"floating checkers in column {c}")
        if p1.bit_count() - p2.bit_count() not in (0, 1):
            raise ValueError("checker counts inconsistent with alternating play")
        if s.current_player != mark:
            raise ValueError(f"mark={mark} does not match side to move ({s.current_player}) for this board")
        s.cur = p1 if mark == 1 else p2
        s.won = has_four(s.cur ^ s.mask, g)
        return s

    @classmethod
    def from_kaggle_observation(cls, observation, configuration=None) -> "State":
        def get(o, k, d=None):
            if o is None:
                return d
            if isinstance(o, dict):
                return o.get(k, d)
            return getattr(o, k, d)
        rows = int(get(configuration, "rows", 6) or 6)
        cols = int(get(configuration, "columns", 7) or 7)
        inarow = int(get(configuration, "inarow", 4) or 4)
        return cls.from_board(get(observation, "board"), int(get(observation, "mark")), rows, cols, inarow)

    def __repr__(self):
        b = self.to_board()
        sym = {0: ".", 1: "X", 2: "O"}
        return "\n".join("".join(sym[b[r * self.cols + c]] for c in range(self.cols)) for r in range(self.rows))


def random_opening(rng, plies, rows=6, cols=7, inarow=4):
    """`plies` random legal moves that leave a non-terminal position (list of columns)."""
    while True:
        s, moves = State(rows, cols, inarow), []
        for _ in range(plies):
            lm = s.legal_moves()
            m = int(lm[int(rng.integers(len(lm)))])
            s.play(m)
            moves.append(m)
        if not s.is_terminal():
            return moves


def random_state(rng, rows=6, cols=7, inarow=4, max_plies=None, stop_at_terminal=False) -> State:
    """Random reachable, non-terminal position by playing random legal moves."""
    while True:
        s = State(rows, cols, inarow)
        n = int(rng.integers(0, (max_plies or rows * cols) + 1))
        ok = True
        for _ in range(n):
            lm = s.legal_moves()
            if not lm:
                break
            s.play(int(lm[int(rng.integers(len(lm)))]))
            if s.is_terminal():
                ok = False
                break
        if ok and not s.is_terminal():
            return s


# --------------------------------------------------------------------------------------------------
# Slow, obviously-correct reference implementation (for cross-checking only)
# --------------------------------------------------------------------------------------------------
class ReferenceGame:
    """2-D list board, row 0 = top. Straightforward scanning rules, no bit tricks."""

    def __init__(self, rows=6, cols=7, inarow=4):
        self.rows, self.cols, self.inarow = rows, cols, inarow
        self.grid = [[0] * cols for _ in range(rows)]
        self.player = 1
        self.winner = 0

    def legal_moves(self):
        return [] if self.winner else [c for c in range(self.cols) if self.grid[0][c] == 0]

    def play(self, col):
        assert self.grid[0][col] == 0 and not self.winner
        r = max(r for r in range(self.rows) if self.grid[r][col] == 0)
        self.grid[r][col] = self.player
        if self.has_line(self.player):
            self.winner = self.player
        self.player = 3 - self.player

    def has_line(self, p):
        R, C, K = self.rows, self.cols, self.inarow
        for r in range(R):
            for c in range(C):
                for dr, dc in ((0, 1), (1, 0), (1, 1), (1, -1)):
                    if all(0 <= r + dr * i < R and 0 <= c + dc * i < C and self.grid[r + dr * i][c + dc * i] == p
                           for i in range(K)):
                        return True
        return False

    def is_draw(self):
        return not self.winner and all(self.grid[0][c] != 0 for c in range(self.cols))

    def flat_board(self):
        return [x for row in self.grid for x in row]

# ============================== az_mcts.py ==============================
"""PUCT-guided MCTS (AlphaZero style). Torch-free: it talks to any evaluator with

    evaluator.evaluate(planes[B,P,R,C] float32, legal[B,C] bool) -> (priors[B,C] float, values[B] float)

where priors are a softmax over LEGAL columns only (exactly 0 elsewhere) and values are from the perspective
of the player to move (+1 win, -1 loss). The same file is embedded in the NumPy-only submission.

Formulation
    select  a* = argmax_a  Q(a) + c_puct * P(a) * sqrt(max(1, sum_b N(b))) / (1 + N(a)),   Q = W/N (0 if N=0)
    leaf    network value (no rollouts); terminal leaf: previous mover has won -> -1 for the player to move
    backup  value flips sign every ply (zero-sum)
"""

import math
import time

import numpy as np



class BaseEvaluator:
    n_planes = 2

    def __init__(self):
        self.n_evals = 0
        self.n_calls = 0
        self.eval_seconds = 0.0

    def _forward(self, planes, legal):
        raise NotImplementedError

    def evaluate(self, planes, legal):
        t = time.perf_counter()
        out = self._forward(planes, legal)
        self.eval_seconds += time.perf_counter() - t
        self.n_evals += len(planes)
        self.n_calls += 1
        return out


class UniformEvaluator(BaseEvaluator):
    """Uniform priors over legal moves, value 0 (an 'untrained, uninformative' evaluator for tests)."""

    def _forward(self, planes, legal):
        p = legal.astype(np.float64)
        return p / p.sum(axis=1, keepdims=True), np.zeros(len(planes))


class Node:
    __slots__ = ("P", "N", "W", "children", "legal", "total")

    def __init__(self, priors, legal):
        n = len(priors)
        self.P = priors
        self.legal = legal
        self.N = np.zeros(n, dtype=np.float64)
        self.W = np.zeros(n, dtype=np.float64)
        self.children = [None] * n
        self.total = 0


class Search:
    """One MCTS tree rooted at `root_state`. Step-wise API so many searches can share batched NN calls:
        req = search.begin_sim()     # None when the simulation resolved itself (terminal / cache hit)
        search.finish_sim(priors, v) # when begin_sim returned a state to evaluate
    """

    def __init__(self, root_state: State, c_puct=1.5, cache=None, noise_rng=None, alpha=1.0, eps=0.25,
                 root: Node | None = None, cache_max=200_000):
        self.root_state = root_state
        self.c = c_puct
        self.cache = cache if cache is not None else {}
        self.cache_max = cache_max
        self.noise_rng, self.alpha, self.eps = noise_rng, alpha, eps   # noise only if noise_rng is not None
        self.root = None
        self.sims = 0
        self._pending = None
        self.root_P_clean = None
        if root is not None:
            self.root = root
            self._apply_noise()

    # ---- root noise (self-play only)
    def _apply_noise(self):
        if self.noise_rng is None:
            return
        r = self.root
        self.root_P_clean = r.P
        idx = np.flatnonzero(r.legal)
        noise = self.noise_rng.dirichlet([self.alpha] * len(idx))
        P = r.P.copy()
        P[idx] = (1 - self.eps) * r.P[idx] + self.eps * noise
        r.P = P

    def _select(self, node: Node) -> int:
        sq = math.sqrt(max(1, node.total))
        q = node.W / np.maximum(node.N, 1)
        score = q + self.c * node.P * sq / (1.0 + node.N)
        score[~node.legal] = -np.inf
        return int(np.argmax(score))

    def _store(self, key, entry):
        if len(self.cache) >= self.cache_max:
            self.cache.clear()
        self.cache[key] = entry

    def _backup(self, path, v):
        for node, a in reversed(path):
            v = -v
            node.N[a] += 1
            node.W[a] += v
            node.total += 1

    def begin_sim(self):
        if self.root is None:
            st = self.root_state
            key = st.to_key()
            hit = self.cache.get(key)
            if hit is not None:
                self.root = Node(hit[0], hit[2])
                self._apply_noise()
                return None
            self._pending = (None, st, key)
            return st
        node = self.root
        state = self.root_state.copy()
        path = []
        size = state.g.size
        while True:
            a = self._select(node)
            path.append((node, a))
            state.play(a)
            if state.won:
                v = -1.0
                break
            if state.moves == size:
                v = 0.0
                break
            child = node.children[a]
            if child is None:
                key = state.to_key()
                hit = self.cache.get(key)
                if hit is not None:
                    node.children[a] = Node(hit[0], hit[2])
                    v = hit[1]
                    break
                self._pending = (path, state, key)
                return state
            node = child
        self._backup(path, v)
        self.sims += 1
        return None

    def finish_sim(self, priors, value):
        path, state, key = self._pending
        self._pending = None
        legal = np.zeros(len(priors), dtype=bool)
        legal[state.legal_moves()] = True
        priors = np.asarray(priors, dtype=np.float64)
        value = float(value)
        self._store(key, (priors, value, legal))
        if path is None:
            self.root = Node(priors, legal)
            self._apply_noise()
            return
        node, a = path[-1]
        node.children[a] = Node(priors, legal)
        self._backup(path, value)
        self.sims += 1

    # ---- results
    def visits(self):
        return self.root.N.copy()

    def root_value(self):
        """Mean value of the root for the player to move."""
        t = self.root.N.sum()
        return float(self.root.W.sum() / t) if t > 0 else 0.0

    def best_move(self) -> int:
        r = self.root
        if r.N.sum() == 0:                                   # policy-only
            return int(np.argmax(np.where(r.legal, r.P, -1.0)))
        top = r.N.max()
        cand = np.flatnonzero(r.N == top)
        q = r.W[cand] / np.maximum(r.N[cand], 1)
        return int(cand[int(np.argmax(q))])

    def sample_move(self, rng, temperature=1.0) -> int:
        n = self.root.N
        if n.sum() == 0:
            p = np.where(self.root.legal, self.root.P, 0.0)
        else:
            p = n ** (1.0 / temperature)
        p = p / p.sum()
        return int(rng.choice(len(p), p=p))

    def policy_target(self):
        n = self.root.N
        if n.sum() == 0:
            p = np.where(self.root.legal, self.root.P, 0.0)
            return p / p.sum()
        return n / n.sum()

    def subtree(self, *actions):
        """Return the Node reached by playing `actions` from the root, or None if not expanded."""
        node = self.root
        for a in actions:
            if node is None:
                return None
            node = node.children[a]
        return node


def _eval_one(evaluator, state: State):
    planes = state.to_planes(getattr(evaluator, "n_planes", 2))[None]
    legal = np.zeros((1, state.cols), dtype=bool)
    legal[0, state.legal_moves()] = True
    pri, val = evaluator.evaluate(planes, legal)
    return pri[0], val[0]


class AZPlayer:
    """Sequential (one game at a time) PUCT agent with a simulation and/or wall-clock budget.
    sims=0 -> policy only (argmax of the network prior). Noise/temperature are OFF by default (evaluation mode)."""

    def __init__(self, evaluator, sims: int | None = 200, time_limit: float | None = None, c_puct: float = 1.5,
                 noise: bool = False, alpha: float = 1.0, eps: float = 0.25, temp_moves: int = 0,
                 reuse: bool = False, seed: int = 0, cache_max: int = 200_000, max_sims: int | None = None):
        self.ev, self.sims, self.time_limit, self.c = evaluator, sims, time_limit, c_puct
        self.noise, self.alpha, self.eps, self.temp_moves, self.reuse = noise, alpha, eps, temp_moves, reuse
        self.rng = np.random.default_rng(seed)
        self.cache: dict = {}
        self.cache_max = cache_max
        self.max_sims = max_sims
        self.last_search: Search | None = None
        self.last_sims = 0
        self.name = f"az(sims={sims}" + (f",t={time_limit}" if time_limit else "") + f",c={c_puct})"
        self.total_sims = 0

    def new_game(self):
        self.last_search = None
        self.cache.clear()

    def _reuse_root(self, state: State):
        """Find `state` among descendants (<=2 plies) of the previous search tree."""
        ls = self.last_search
        if not (self.reuse and ls is not None and ls.root is not None):
            return None
        key = state.to_key()
        base = ls.root_state
        for a in base.legal_moves():
            s1 = base.child(a)
            if s1.to_key() == key:
                return ls.subtree(a)
            if s1.is_terminal():
                continue
            for b in s1.legal_moves():
                if s1.child(b).to_key() == key:
                    return ls.subtree(a, b)
        return None

    def search(self, state: State) -> Search:
        root = self._reuse_root(state)
        s = Search(state.copy(), self.c, self.cache, self.rng if self.noise else None, self.alpha, self.eps,
                   root=root, cache_max=self.cache_max)
        deadline = time.perf_counter() + self.time_limit if self.time_limit else None
        target = self.sims if self.sims is not None else (self.max_sims or 10 ** 9)
        if self.max_sims is not None:
            target = min(target, self.max_sims)
        while s.root is None or s.sims < target:
            if s.root is not None and deadline is not None and s.sims >= 1 and time.perf_counter() >= deadline:
                break
            req = s.begin_sim()
            if req is not None:
                p, v = _eval_one(self.ev, req)
                s.finish_sim(p, v)
        self.last_search = s
        self.last_sims = s.sims
        self.total_sims += s.sims
        return s

    def select(self, state: State) -> int:
        legal = state.legal_moves()
        if len(legal) == 1:
            self.last_search = None
            return legal[0]
        s = self.search(state)
        if self.temp_moves and state.moves < self.temp_moves:
            return s.sample_move(self.rng, 1.0)
        return s.best_move()

    __call__ = select


# --------------------------------------------------------------------------------------------------
# Batched multi-game driver (self-play and arena)
# --------------------------------------------------------------------------------------------------
class PlayerSpec:
    def __init__(self, evaluator, sims=100, c_puct=1.5, noise=False, alpha=1.0, eps=0.25, temp_moves=0,
                 reuse=False, cache_max=200_000):
        self.ev, self.sims, self.c, self.noise = evaluator, sims, c_puct, noise
        self.alpha, self.eps, self.temp_moves, self.reuse, self.cache_max = alpha, eps, temp_moves, reuse, cache_max


class GameResult:
    def __init__(self):
        self.moves = []          # all plies incl. opening
        self.winner = 0          # 0 draw, 1, 2
        self.planes = []         # recorded positions (to-move perspective)
        self.pis = []
        self.movers = []         # player number (1/2) to move at each recorded position
        self.sims = 0

    def values(self):
        """Value target per recorded position, from the perspective of the player to move there."""
        if self.winner == 0:
            return [0.0] * len(self.movers)
        return [1.0 if m == self.winner else -1.0 for m in self.movers]


class _Game:
    def __init__(self, players, seed, opening, rows, cols, inarow, record):
        self.players = players          # (spec for player 1, spec for player 2)
        self.rng = np.random.default_rng(seed)
        self.state = State(rows, cols, inarow)
        self.res = GameResult()
        self.record = record
        self.search = None
        self.caches = {}
        self.prev = [None, None]
        self.done = False
        for a in opening:
            self._play(a)

    def _play(self, a):
        mover = self.state.current_player
        self.state.play(a)
        self.res.moves.append(int(a))
        if self.state.won:
            self.res.winner, self.done = mover, True
        elif self.state.moves == self.state.g.size:
            self.done = True

    def _start(self):
        idx = self.state.current_player - 1
        spec = self.players[idx]
        cache = self.caches.setdefault(id(spec.ev), {})
        root = self._reuse(self.prev[idx]) if spec.reuse else None
        self.search = Search(self.state.copy(), spec.c, cache, self.rng if spec.noise else None, spec.alpha,
                             spec.eps, root=root, cache_max=spec.cache_max)
        self.prev[idx] = self.search

    def _reuse(self, prev):
        """Re-root this player's previous tree at the current position (found <=2 plies below its root)."""
        if prev is None or prev.root is None:
            return None
        key = self.state.to_key()
        base = prev.root_state
        for a in base.legal_moves():
            s1 = base.child(a)
            if s1.to_key() == key:
                return prev.subtree(a)
            if s1.is_terminal():
                continue
            for b in s1.legal_moves():
                if s1.child(b).to_key() == key:
                    return prev.subtree(a, b)
        return None

    def advance(self):
        """Run until a network evaluation is needed (returns (evaluator, n_planes, state)) or the game ends."""
        while not self.done:
            legal = self.state.legal_moves()
            if len(legal) == 1:                     # forced move, nothing to learn / search
                self.search = None
                self._play(legal[0])
                continue
            if self.search is None or self.search.root_state.moves != self.state.moves:
                self._start()
            s = self.search
            spec = self.players[self.state.current_player - 1]
            while s.root is None or s.sims < spec.sims:
                req = s.begin_sim()
                if req is not None:
                    return spec.ev, req
            self._finish_move(s, spec)
        return None

    def _finish_move(self, s, spec):
        st = self.state
        if self.record:
            self.res.planes.append(st.to_planes(getattr(spec.ev, "n_planes", 2)))
            self.res.pis.append(s.policy_target().astype(np.float32))
            self.res.movers.append(st.current_player)
        self.res.sims += s.sims
        a = s.sample_move(self.rng, 1.0) if (spec.temp_moves and st.moves < spec.temp_moves) else s.best_move()
        self._play(a)


def run_games_batched(pairs, seeds, openings=None, rows=6, cols=7, inarow=4, record=True):
    """Play len(pairs) games in lockstep. pairs[i] = (PlayerSpec for player 1, PlayerSpec for player 2).
    Each round every unfinished game contributes at most one leaf, and leaves are grouped per evaluator into one
    batched forward pass. Returns a list of GameResult."""
    openings = openings or [[] for _ in pairs]
    games = [_Game(p, s, o, rows, cols, inarow, record) for p, s, o in zip(pairs, seeds, openings)]
    active = [g for g in games if not g.done]
    while active:
        groups: dict = {}
        nxt = []
        for g in active:
            req = g.advance()
            if req is None:
                continue
            ev, st = req
            groups.setdefault(id(ev), (ev, []))[1].append((g, st))
            nxt.append(g)
        for ev, items in groups.values():
            npl = getattr(ev, "n_planes", 2)
            planes = np.zeros((len(items), npl, items[0][1].rows, items[0][1].cols), dtype=np.float32)
            legal = np.zeros((len(items), items[0][1].cols), dtype=bool)
            for i, (g, st) in enumerate(items):
                st.to_planes(npl, out=planes[i])
                legal[i, st.legal_moves()] = True
            pri, val = ev.evaluate(planes, legal)
            for i, (g, st) in enumerate(items):
                g.search.finish_sim(pri[i], val[i])
        active = nxt
    return [g.res for g in games]

# ============================== np_net.py ==============================
"""Pure-NumPy forward pass of the exported policy/value network (no torch import). Batch norm is already folded
into the conv weights by `network.export_weights`, so inference is conv+bias -> ReLU.

arch vector (float32): [type(0=cnn,1=mlp), rows, cols, planes, width_or_hidden, value_hidden]
"""

import time

import numpy as np
from numpy.lib.stride_tricks import sliding_window_view


def load_weights(path_or_file):
    with np.load(path_or_file) as z:
        return {k: z[k].astype(np.float32) for k in z.files}


def masked_softmax(logits, legal):
    z = np.where(legal, logits, -np.inf)
    z = z - z.max(axis=-1, keepdims=True)
    e = np.exp(z)
    e = np.where(legal, e, 0.0)
    return e / e.sum(axis=-1, keepdims=True)


class NumpyNet:
    n_planes = 2

    def __init__(self, weights: dict):
        w = weights
        a = w["arch"]
        self.kind = int(a[0])
        self.rows, self.cols, self.planes = int(a[1]), int(a[2]), int(a[3])
        self.n_planes = self.planes
        self.w = {k: np.ascontiguousarray(v, dtype=np.float32) for k, v in w.items() if k != "arch"}
        if self.kind == 0:
            for i in range(3):   # (out, in, 3, 3) -> (in*9, out) for matmul against sliding windows
                W = self.w[f"conv{i}_w"]
                self.w[f"conv{i}_m"] = np.ascontiguousarray(W.reshape(W.shape[0], -1).T)

    def _conv(self, x, i):
        """x: [B,H,W,Cin] channels-last -> [B,H,W,Cout]."""
        B, H, W, C = x.shape
        xp = np.pad(x, ((0, 0), (1, 1), (1, 1), (0, 0)))
        win = sliding_window_view(xp, (3, 3), axis=(1, 2))        # [B,H,W,C,3,3]
        cols = win.reshape(B * H * W, C * 9)
        out = cols @ self.w[f"conv{i}_m"] + self.w[f"conv{i}_b"]
        return np.maximum(out, 0).reshape(B, H, W, -1)

    def forward(self, planes):
        """planes [B,P,R,C] -> (policy logits [B,C], value [B]); matches the torch module in eval mode."""
        x = np.asarray(planes, dtype=np.float32)
        w = self.w
        if self.kind == 0:
            x = np.ascontiguousarray(x.transpose(0, 2, 3, 1))
            for i in range(3):
                x = self._conv(x, i)
            x = np.ascontiguousarray(x.transpose(0, 3, 1, 2)).reshape(len(x), -1)   # torch flatten order (C,H,W)
        else:
            x = x.reshape(len(x), -1)
            x = np.maximum(x @ w["l1_w"].T + w["l1_b"], 0)
            x = np.maximum(x @ w["l2_w"].T + w["l2_b"], 0)
        logits = x @ w["pol_w"].T + w["pol_b"]
        h = np.maximum(x @ w["v1_w"].T + w["v1_b"], 0)
        v = np.tanh(h @ w["v2_w"].T + w["v2_b"])[:, 0]
        return logits, v


class NumpyEvaluator:
    """Same interface as az_mcts evaluators."""

    def __init__(self, weights: dict):
        self.net = NumpyNet(weights)
        self.n_planes = self.net.planes
        self.n_evals = 0
        self.n_calls = 0
        self.eval_seconds = 0.0

    @classmethod
    def from_file(cls, path):
        return cls(load_weights(path))

    def evaluate(self, planes, legal):
        t = time.perf_counter()
        logits, v = self.net.forward(planes)
        p = masked_softmax(logits.astype(np.float64), legal)
        self.eval_seconds += time.perf_counter() - t
        self.n_evals += len(planes)
        self.n_calls += 1
        return p, v.astype(np.float64)

